style.css:
@-moz-document url-prefix("chrome://"), url-prefix("about:"), url-prefix("chrome-extension://") {
/* Cores do tema Cyberpunk */
    :root {
        --cyberpunk-pink: #ff00ff;
        --cyberpunk-blue: #00ffff;
        --cyberpunk-purple: #9d00ff;
        --cyberpunk-yellow: #ffff00;
        --cyberpunk-dark: #0a0a0a;
        --cyberpunk-darker: #050505;
        --cyberpunk-neon-glow: 0 0 10px var(--cyberpunk-pink),
                             0 0 20px var(--cyberpunk-pink),
                             0 0 30px var(--cyberpunk-pink);
    }

    /* Fundo geral */
    body, html, #background, .background {
        background: linear-gradient(135deg, var(--cyberpunk-darker) 0%, var(--cyberpunk-dark) 100%) !important;
        color: var(--cyberpunk-blue) !important;
        font-family: 'Courier New', monospace !important;
    }

    /* Abas */
    .tab {
        background: linear-gradient(45deg, var(--cyberpunk-dark) 0%, #1a1a1a 100%) !important;
        border: 1px solid var(--cyberpunk-pink) !important;
        border-radius: 8px 8px 0 0 !important;
        box-shadow: var(--cyberpunk-neon-glow) !important;
        margin-right: 2px !important;
    }

    .tab.active {
        background: linear-gradient(45deg, var(--cyberpunk-purple) 0%, var(--cyberpunk-pink) 100%) !important;
        border-bottom: 2px solid var(--cyberpunk-yellow) !important;
    }

    .tab-text {
        color: var(--cyberpunk-blue) !important;
        text-shadow: 0 0 5px var(--cyberpunk-blue) !important;
        font-weight: bold !important;
    }

    .tab.active .tab-text {
        color: var(--cyberpunk-yellow) !important;
        text-shadow: 0 0 8px var(--cyberpunk-yellow) !important;
    }

    /* Barra de endereço */
    #omnibox, .omnibox, .urlbar {
        background: rgba(10, 10, 10, 0.9) !important;
        border: 2px solid var(--cyberpunk-blue) !important;
        border-radius: 20px !important;
        box-shadow: 0 0 15px var(--cyberpunk-blue) !important;
        color: var(--cyberpunk-yellow) !important;
    }

    /* Botões */
    button {
        background: linear-gradient(45deg, var(--cyberpunk-dark) 0%, #2a2a2a 100%) !important;
        border: 1px solid var(--cyberpunk-pink) !important;
        border-radius: 4px !important;
        color: var(--cyberpunk-blue) !important;
        text-shadow: 0 0 5px var(--cyberpunk-blue) !important;
        transition: all 0.3s ease !important;
    }

    button:hover {
        background: linear-gradient(45deg, var(--cyberpunk-pink) 0%, var(--cyberpunk-purple) 100%) !important;
        box-shadow: var(--cyberpunk-neon-glow) !important;
        color: var(--cyberpunk-yellow) !important;
        transform: translateY(-2px) !important;
    }

    /* Barra de favoritos */
    #bookmarks-bar, .bookmarks-bar {
        background: rgba(5, 5, 5, 0.95) !important;
        border-top: 1px solid var(--cyberpunk-blue) !important;
        border-bottom: 1px solid var(--cyberpunk-pink) !important;
    }

    .bookmark-item {
        color: var(--cyberpunk-yellow) !important;
        text-shadow: 0 0 5px var(--cyberpunk-yellow) !important;
        padding: 4px 8px !important;
        border-radius: 3px !important;
        transition: all 0.3s ease !important;
    }

    .bookmark-item:hover {
        background: var(--cyberpunk-pink) !important;
        box-shadow: 0 0 10px var(--cyberpunk-pink) !important;
        color: var(--cyberpunk-dark) !important;
    }

    /* Scrollbars */
    ::-webkit-scrollbar {
        width: 12px !important;
        background: var(--cyberpunk-dark) !important;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(45deg, var(--cyberpunk-pink) 0%, var(--cyberpunk-blue) 100%) !important;
        border-radius: 6px !important;
        box-shadow: 0 0 10px var(--cyberpunk-pink) !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: linear-gradient(45deg, var(--cyberpunk-yellow) 0%, var(--cyberpunk-purple) 100%) !important;
    }

    /* Menu contextual */
    .context-menu {
        background: linear-gradient(135deg, var(--cyberpunk-dark) 0%, #1a1a1a 100%) !important;
        border: 2px solid var(--cyberpunk-blue) !important;
        box-shadow: 0 0 20px var(--cyberpunk-pink) !important;
        border-radius: 8px !important;
    }

    .context-menu-item {
        color: var(--cyberpunk-blue) !important;
        border-bottom: 1px solid rgba(0, 255, 255, 0.3) !important;
        transition: all 0.3s ease !important;
    }

    .context-menu-item:hover {
        background: var(--cyberpunk-pink) !important;
        color: var(--cyberpunk-dark) !important;
        text-shadow: 0 0 5px var(--cyberpunk-dark) !important;
    }

    /* Barra de status */
    #status-bar, .status-bar {
        background: linear-gradient(90deg, var(--cyberpunk-purple) 0%, var(--cyberpunk-pink) 100%) !important;
        color: var(--cyberpunk-yellow) !important;
        text-shadow: 0 0 5px var(--cyberpunk-yellow) !important;
        border-top: 2px solid var(--cyberpunk-blue) !important;
    }

    /* Efeitos de texto cyberpunk */
    h1, h2, h3, h4, h5, h6 {
        color: var(--cyberpunk-pink) !important;
        text-shadow: 0 0 10px var(--cyberpunk-pink),
                   0 0 20px var(--cyberpunk-pink) !important;
        font-weight: bold !important;
        letter-spacing: 1px !important;
    }

    /* Input fields */
    input, textarea, select {
        background: rgba(10, 10, 10, 0.8) !important;
        border: 1px solid var(--cyberpunk-blue) !important;
        color: var(--cyberpunk-yellow) !important;
        border-radius: 4px !important;
        padding: 5px !important;
    }

    input:focus, textarea:focus {
        box-shadow: 0 0 10px var(--cyberpunk-blue) !important;
        border-color: var(--cyberpunk-yellow) !important;
    }

    /* Links */
    a {
        color: var(--cyberpunk-blue) !important;
        text-shadow: 0 0 5px var(--cyberpunk-blue) !important;
        text-decoration: none !important;
        transition: all 0.3s ease !important;
    }

    a:hover {
        color: var(--cyberpunk-pink) !important;
        text-shadow: 0 0 10px var(--cyberpunk-pink) !important;
        text-decoration: underline !important;
    }
}
